mapper.select:
select l.ASSET_ID      as assetAId,
       PORT_INDEX      as portAId,
       LINK_ASSET_ID   as assetBId,
       LINK_PORT       as portBId
from (
         select asset_id
         from ASSET_ATTACH
         where ROOM_ID = #{roomId1}
            or ROOM_ID = #{roomId2}
     ) a
         join ASSET_LINK_ASSET l on l.ASSET_ID = a.ASSET_ID
where LINK_ASSET_ID is not null
